def transform(g):
 h,w=len(g),len(g[0]); out=[r[:] for r in g]; seen=set()
 for i in range(h):
  for j in range(w):
   if g[i][j]==8 or (i,j) in seen: continue
   q=[(i,j)]; seen.add((i,j)); comp=[]
   for a,b in q:
    comp.append((a,b))
    for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
     if 0<=x<h and 0<=y<w and g[x][y]!=8 and (x,y) not in seen: seen.add((x,y)); q.append((x,y))
   rs=[a for a,b in comp]; cs=[b for a,b in comp]; r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
   colored=[(a,b) for a,b in comp if g[a][b] not in (0,8)]
   if not colored: continue
   pr0,pr1=min(a for a,b in colored),max(a for a,b in colored); pc0,pc1=min(b for a,b in colored),max(b for a,b in colored)
   pat=[[g[a][b] for b in range(pc0,pc1+1)] for a in range(pr0,pr1+1)]
   for a,b in comp: out[a][b]=pat[(a-pr0)%len(pat)][(b-pc0)%len(pat[0])]
 return out
